(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sm"] = {"ui":{"skip":"Alu i le anotusi","back":"← Toe foʻi i AI-gile","lang.button":"Gagana: {name}","lang.dialog":"Filifili se gagana","lang.search":"Suʻe gagana","lang.none":"E leai se gagana e tutusa","lang.notYet":"E leʻi faaliliuina le {name}","theme.aria":"Sui le autu: malamalama, pogisa pe uliuli","theme.toLight":"Sui i le autu malamalama","theme.toDark":"Sui i le autu pogisa","theme.toBlack":"Sui i le autu uliuli (uliuli moni, lelei mo lau OLED)","words.underline":"Tusi se laina i lalo o nei upu i le itulau","words.underlineHelp":"Tuu le kesa i luga pe tago i se upu e iai togi e vaai ai i lona uiga.","words.col.todo":"Kata ua filifilia mo nei: o le a amata e le 'au i nei mea.","words.col.doing":"O loʻo galulue se AI i le kata nei i le taimi nei.","words.col.review":"Ua uma e le AI e tasi le galuega; e siaki e se isi AI a o lei oʻo atu ia te oe.","words.col.verify":"O loʻo faatali ia te oe: faamaoni ma e fai mai pe e galue.","words.col.team":"O ou faamatalaga poʻo tali, o loʻo faatali mo le 'au e ave.","words.col.done":"Ua uma ma talia.","index.title":"AI-gile: lau ʻau AI faatupu polokalama, i le tasi laupapa","index.description":"O le AI-gile o se laupapa kanban mo ʻau tusi polokalama AI. E latou galulue a e moe oe; e te maua se faaputuga puupuu o mea e te filifili ai, suʻesuʻe ma talia.","hero.logoAlt":"Ata o le laupapa AI-gile","hero.h1.html":"Lau ʻau AI faatupu polokalama, i le tasi&nbsp;laupapa.","hero.alpha":"🐣 Pre-alpha tapunia","hero.alphaTitle":"Muamua ma le i uma: faafetai i lou taumafai!","hero.lede":"E latou fausia a e moe oe. E te ala mai i se faaputuga puupuu: ni nai fesili, ni nai mea e suʻe, ma le tasi pe lua taimane viole. Kiliki, talia, ma toe foʻi i lau kofe.","dl.windows":"Polokalama Windows","dl.browser":"Tatala i lau browser","dl.messenger":"📱 Messenger mo lau telefoni","dl.soon":"E le o toe umi","dl.notify":"🔔 Logo mai ina ua tatala","dl.notifySmall":"Alpha poʻo le beta","hero.secondary":"Agile, ae e le manaʻomia lava e le ʻau le kofe o le fono puupuu. (Ae latou te faia pea fono puupuu.)","pitch.h2":"AI-gile i le tele o upu e te manaʻo ai","pitch.lede":"Filifili se umi, mai le upu e tasi i le 144. O umi taʻitasi o se faamatalaga tuʻufaatasi, na tusia mo lena lapopoa. Toso le faʻasolo pe faaaoga ki aū o le keyboard.","pitch.rangeLabel":"Umi i upu","pitch.dice":"🎲 isi lomiga","pitch.words.one":"{n} upu","pitch.words.other":"{n} upu","pitch.letters.one":"{n} mataitusi","pitch.letters.other":"{n} mataitusi","pitch.chars.one":"{n} mataitusi","pitch.chars.other":"{n} mataitusi","count.line.html.one":"{n} kāte i luga o le laupapa nei","count.line.html.other":"{n} kāte i luga o le laupapa nei","people.humans.html.one":"👥 {n} tagata","people.humans.html.other":"👥 {n} tagata","people.agents.html.one":"🤖 {n} sui","people.agents.html.other":"🤖 {n} sui","people.working.html.one":"⚡ {n} o loʻo galulue nei","people.working.html.other":"⚡ {n} o loʻo galulue nei","pre.title":"AI-gile: o loʻo fausia se mea","pre.description":"O loʻo fausia se mea iinei: o se laupapa e fausia ai e ʻau AI mea e te manaʻo ai, ma aʻoaʻo atu ia te oe a o latou galulue. O se pre-alpha tapunia ma uo mo le taimi nei.","pre.h1":"O loʻo fausia se mea iinei. 🤫","pre.line":"O se laupapa e fausia ai e ʻau AI mea e te manaʻo ai, ma aʻoaʻo atu ia te oe a o latou galulue. O se pre-alpha tapunia ma uo mo le taimi nei.","pre.btn":"🔔 Logo mai ina ua tatala","pre.peek":"I tua o le tioata: le laupapa moni, ola. O kāte uma o se laina lanu.","pre.peekFake":"I tua o le tioata: le foliga o se laupapa o loʻo galue.","pre.night":"🌙 O le leoleo o le pō e pule · 😴 o loo malolo le tagata","features.aria":"O le a le mea e faia","f.pile.h":"Le tasi faaputuga mo oe","f.pile.html":"O <b>Mo oe</b> e tuufaatasia mea uma o loo faatali ia te oe, i poloketi uma: fesili, mea e suʻesuʻe, galuega e na o le tagata e mafai ona faia. O lau laina e taʻu atu le mea o le a sosoo ai ma le umi.","f.sleep.h":"ʻAu e galulue a e moe oe","f.sleep.p":"O poloketi taʻitasi e iai se taʻitaʻi ma se ʻau o sooupu AI. Tusi se faamatalaga i luga o se kāte ona ala lea o le ʻau, faia le galuega, ma toe tuuina atu ma laasaga e mafai e se tagata vaivai ona mulimuli ai.","f.tester.h":"E muamua siaki e se AI suʻesuʻe","f.tester.p":"Aʻo leʻi oo atu se mea ia te oe, e mulimuli le suʻesuʻe i laasaga i se kopi o le polokalama ma faaali le mea na ia vaai i ai, faatasi ma se ata o le lau. Iloilo mea na pasia ma talia i le tasi kiliki.","f.proof.h":"Faamaoniga, e le o folafolaga","f.proof.p":"O le tuuina atu taʻitasi e faaali ai le mea na suia: faila, eseesega, ata o le lau. E te le manaʻomia ona tatalaina polokalama uma e vaai pe ua uma.","f.chat.h":"Talanoa ma ou taʻitaʻi","f.chat.p":"O se laina e pei o Discord: le tasi ata mo poloketi taʻitasi, taimane viole mo mea e manaʻomia ai oe. Auina atu se manatu i se taʻitaʻi; e ia faia ma kāte ma se fuafuaga, faatasi ma se faamau ✅ Alu.","f.tidy.h":"E faʻatulaga e ia lava","f.tidy.p":"O kāte felavasaʻi e tuufaatasia, o ulutala fenumiai e faasaʻoina, ma o se siakiga token e tausia le code ia mamā. E le tele mea e sui ai, e le tele mea e mafaufau ai.","f.private.h":"O oe lava, i lau komepiuta","f.private.li1":"E galue le laupapa i lau lava masini ma e na o oe e tali atu ai.","f.private.li2":"O feʻau tuusao i le va o tagata ua faamaufaailogaina mai le pito i le pito.","f.private.li3":"E leai ni akauni, e leai ni mea e siaki ai oe, e leai ni cookies.","f.lang.h":"I lau gagana","f.lang.p":"E sili atu i le 120 gagana, mai le Holani, Uelisi ma Iapani i le pirate, Yoda ma Klingon, faatasi ma se sui vave i le Igilisi mo upu faʻapitoa.","f.service.h":"Mai se manatu i se auaunaga moni","f.service.p":"Na e fausia se mea i le AI ua faaaoga nei e tagata? Faailoga o se auaunaga ma o le a fesoasoani le laupapa ia e faatautaia lelei: siakiga uptime, se itulau o le tulaga lautele, faalavelave ma se tusiga, suiga e manaʻomia se Go, faʻasaoga e siakiina i aso uma. E aʻoaʻo atu e le Fesoasoani laasaga taʻitasi a o e alu.","msgr.h2":"AI-gile Messenger: lau ʻau i lau taga","msgr.p1":"Talanoa ma lau ʻau AI e aunoa ma le tatalaina o le laupapa. Talatalanoa ma ou taʻitaʻi poloketi ma au uo, ma vaai i laasaga suʻega o se kāte ma tali i ai, mai lau telefoni uma lava.","msgr.p2":"Ina ia fesoʻotaʻi, sikeni se QR code i lau laupapa. O le taimi muamua? O se talanoaga demo faauo o le a faʻaali atu ia te oe mea uma.","msgr.when":"Android muamua, ona sosoo ai lea ma se lomiga i luga o le upega tafaʻilagi mo telefoni ma iPhone.","msgr.who":"Lou taʻitaʻi poloketi","msgr.b1":"Ua sauni le toe faaleleia o le dark mode. E te manaʻo i laasaga suʻega?","msgr.b2":"Ioe faamolemole!","msgr.b3":"1. Tatala Settings. 2. Filifili Dark. E foliga saʻo?","tl.aria":"Taimi mai le talanoaga muamua i le fuafuaga","tl.h2":"Mai le talanoaga muamua i mea o le a sosoo ai","tl.lede":"Aso ma taimi moni, i lou itu taimi. Ina ua mavae le aso nei o le fuafuaga, e leai ni aso o folafolaina.","tl.today":"Aso nei","tl.planned":"fuafuaina","tl.doing":"o faia","tl.cards.one":"{n} kāte","tl.cards.other":"{n} kāte","join.h2":"Auai mai","join.lede":"O loo fausia AI-gile e se tagata ese e iai lana ʻava, e iai lona AuDHD ma ni nai taua ma le soifua mālōlōina o le mafaufau, ma le tele o sooupu onosaʻi. O le taimi nei e faalilolilo, i se alpha tapunia ma uo. E te manaʻo e taumafai pe a tatala?","join.btn":"Lesisita le fiafia","join.small":"O le a matou tusi atu i le imeli, e leai se isi mea","footer.tag":"AI-gile. E leai ni mea e siaki ai oe, e leai ni cookies, e leai se kofe o le fono puupuu.","footer.licence":"Laisene pisinisi","footer.status":"Tulaga","footer.privacy":"Mea matou te teuina","footer.thanks":"Valaʻau, faafetai ia ChilledChat","form.sending":"O auina atu…","form.failed":"E leʻi galue: toe taumafai mulimuli ane.","form.offline":"E leʻi mafai ona oo atu i AI-gile: toe taumafai mulimuli ane.","form.keep":"Matou te faaaogaina na o le tali atu ia te oe, ona tapeese ai lea. E leai ni mea e siaki ai oe, e leai ni cookies.","form.keepLink":"Mea matou te teuina","interest.title":"AI-gile: logo mai ina ua tatala le alpha","interest.description":"Tuu mai lau imeli e iloa ai pe a tatala le alpha poʻo le beta tapunia o AI-gile.","interest.h1":"🔔 Logo mai ina ua tatala","interest.lede":"O AI-gile o loo i le pre-alpha tapunia. Tuu mai lau imeli ona matou tusi atu lea i le tasi taimi, pe a iai se avanoa mo oe.","interest.email":"Lau imeli","interest.which":"O le fea suega?","interest.alpha":"Alpha tapunia: muamua, ma le faigata, e tele suiga","interest.beta":"Beta: sili atu le mausali, mulimuli ane","interest.both":"Se tasi, po o le fea e muamua mai","interest.submit":"Tuu aʻu i le lisi","interest.thanks":"Faafetai! O iai oe i le lisi.","licence.title":"AI-gile: laisene pisinisi","licence.description":"E te faaaogaina AI-gile i lau pisinisi? Talosaga mo se laisene pisinisi e leai se totogi.","licence.h1":"📜 Laisene pisinisi","licence.lede":"E te faaaogaina AI-gile i le galuega? Taʻu mai po o ai oe ma le mea e te faia. Afai e aogā, e leai se totogi o le laisene.","licence.company":"Kamupani","licence.website":"Uepisaite","licence.what":"O le a le mea e te faia","licence.how":"Le auala e fesoasoani ai i le lalolagi","licence.email":"Imeli","licence.submit":"Talosaga","licence.thanks":"Faafetai! O le a matou toe tali atu i le imeli.","status.title":"Tulaga o AI-gile","status.h1":"Tulaga o AI-gile","status.quiet":"Ua filemu uma","status.intro":"O galue AI-gile i le taimi nei? E siaki e lenei itulau le uepisaite, faasoa o laupapa, telefoni ma le download i minute uma e 5.","status.up":"O galue (tali mai i le {ms} ms)","status.slow":"E leʻi tali mai i le siaki mulimuli, o toe taumafai","status.down":"Ua pau: e leʻi tali mai i siaki mulimuli e lua","status.svc.web":"Uepisaite","status.svc.web.offers":"Lenei saite: o le a le AI-gile, ma le pepa o le fiafia","status.svc.boards":"Faasoa o laupapa","status.svc.boards.offers":"Laupapa lautele, feʻau i le va o uo ma valaaulia","status.svc.calls":"Telefoni","status.svc.calls.offers":"Leo, vitio ma le faasoa o le lau i totonu o AI-gile","status.svc.download":"Download","status.svc.download.offers":"Le polokalama faapipii mo Windows ma fesoʻotaʻiga valaaulia","status.checking":"O siaki…","status.offline":"E le mafai ona oo atu i le auaunaga o le tulaga i le taimi nei (o toe taumafai)","status.updated":"faafouina {ago}","status.justNow":"ua na o nei","status.min":"{n} minute ua mavae","status.hours":"{n} itula ua mavae","status.days":"{n} aso ua mavae","privacy.title":"AI-gile: mea matou te teuina","privacy.h1":"Mea matou te teuina","privacy.lede":"I se faapuupuuga: na o mea e te auina mai, ma e le umi.","privacy.only":"Na o mea e te auina mai: mea e te tusia i se pepa, e pei o lau imeli. E leai se isi mea e uiga ia te oe.","privacy.sealed":"Ua faamaufaailogaina ina ia le mafai e le matou server ona faitau: i lau browser aʻo leʻi alu (i se browser tuai, i le taimi lava e taunuu ai). Na o le matou lava laupapa e mafai ona tatalaina.","privacy.server":"E tapeese mai le server i le taimi lava e oo ai i le matou laupapa. Soo se mea o i ai pea pe a mavae aso e 30 e tapeese lava.","privacy.board":"Matou te teuina i le matou laupapa seʻia matou tali atu ia te oe, ona tapeese ai foi lea iina.","privacy.none":"E leai ni mea e siaki ai oe, e leai ni cookies, e leai ni suʻesuʻega o le faaaogaina.","privacy.local":"O lau gagana ma lau filifiliga o le malamalama po o le pogisa e tumau i lau lava browser. E le auina mai lava i matou.","privacy.ask":"E te manaʻo ia vave ona tapeese? Tali mai i la matou imeli ma taʻu mai.","live.h2":"Matamata i lona fausiaina, ola","live.caption":"Ua natia kāte uma: e te va'ai i foliga o le galuega, e le o ni upu.","live.watching.one":"ola: {n} o matamata","live.watching.other":"ola: {n} o matamata","live.last.now":"Na sii le kāte mulimuli i le taimi nei lava","live.last.min.one":"Na sii le kāte mulimuli i le {n} minute ua mavae","live.last.min.other":"Na sii le kāte mulimuli i minute e {n} ua mavae","live.last.hour.one":"Na sii le kāte mulimuli i le {n} itula ua mavae","live.last.hour.other":"Na sii le kāte mulimuli i itula e {n} ua mavae","live.last.day.one":"Na sii le kāte mulimuli i le {n} aso ua mavae","live.last.day.other":"Na sii le kāte mulimuli i aso e {n} ua mavae","live.offline":"O lo'o malolo sina le fa'amaumauga ola. Toe afio mai a e le'i umi.","live.cols":"Backlog|E fai|O loʻo faia|O loʻo siaki e le 'au|Mo oe e test|Mo le 'au|Ua uma"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Tuuina."]},{"n":2,"texts":["Kanban robots.","Sui, faatulagaina.","Manatu, fausia."]},{"n":3,"texts":["Kanban mo robots.","Manatu e avea gaoioiga.","Kanban sui, leai totogi."]},{"n":5,"texts":["Laupapa kanban e taitaia e sui.","Tusi kāte. E fausia e sui.","Leai totogi, i totonu, suʻesuʻeina, malie."]},{"n":8,"texts":["Laupapa kanban leai totogi e galue ai sui AI.","Tusi se manatu. E fausia e sui. E te talia.","Agile mo se tagata ma robots onosaʻi e tele."]},{"n":13,"texts":["Laupapa kanban i lau komepiuta, e piki kāte ai sui AI e galue.","Tusi se manatu. E fausia e sui. Suʻesuʻe e siaki. Oe e talia.","Leai totogi, leai teugatupe, leai nofoaga mulimuli: se laupapa, ni robots, ma oe e pule."]},{"n":21,"texts":["O le AI-gile o se laupapa kanban mo galulue ma sui AI e tusi polokalama. E latou piki kāte; e te suʻesuʻe ma talia.","Poloketi taʻitasi e iai se taʻitaʻi ma ʻau sui AI. Tusi se faamatalaga i se kāte, ona amata lea o le galuega.","Laupapa galuega totino e leai se totogi, i lau lava komepiuta. E robots le ʻau. O oe e fai atu ioe."]},{"n":34,"texts":["Tuu manatu i luga o le laupapa. E liliu e se ʻau sui AI i gaoioiga e galue, suʻesuʻe, ma toe tuuina atu ma laasaga. E leai se mea ua uma seʻia e fai mai oe.","O le AI-gile o se laupapa kanban na fausia e Rich faatasi ma sui AI o loo ia pulea nei. E leai se totogi, e galue i lau komepiuta, ma faasoa i uo, e le faatauina.","Mafaufau i se laupapa kanban masani, ma koluma mai le Backlog i le Ua uma, ae o kāte e piki e sui AI. Latou lipotia le alualu i luma, fesili pe a tu, ma faatali pea i lau faatagaga."]},{"n":55,"texts":["O le AI-gile o se laupapa kanban e fausia le ʻau i sui AI. O poloketi taʻitasi e iai se taʻitaʻi e fuafuaina le galuega ma fesoasoani e faia. A uma se gaoioiga, e suʻesuʻe e se AI suʻesuʻe ma ave ai se ata o le mataʻitusi, ona alu lea i lau faaputuga. Talia, pe tusi se faamatalaga ona toe faia lea e latou.","Na amata o se auala e mulimuli ai le tagata e tasi i le tele o fonotaga tusi polokalama AI, ona tupu lea i se laupapa moni. E galue i lau masini, e leai se teugatupe, e leai ni nofoaga mulimuli. E leai se totogi mo uo. E le i uma, ia faatalitali i ni pito faigata.","O le faamatalaga faamaoni lea. E tatau pea ona e maua manatu, ma e tatau pea ona e siaki taunuuga. O le AI-gile e faia mea uma i le va: e tausia kāte i le faasologa, ala le sui saʻo pe a e tusi se faamatalaga, faaali saʻo le mea na suia, ma tuu mea uma i se faaputuga puupuu mo oe."]},{"n":89,"texts":["O le AI-gile o se laupapa kanban e leai se totogi i lau komepiuta. I poloketi taʻitasi e iai se ʻau sui AI: se taʻitaʻi e liliu au manatu i kāte ma se fuafuaga, ma fesoasoani e piki kāte. A fausia se mea, e mulimuli se AI suʻesuʻe i laasaga ma faaali le mea na ia vaai i ai. Ona faatali lea i se faaputuga e igoa Mo oe. E te talia, pe tusi se faamatalaga ona toe taumafai lea. E leai se mea e oo i le Ua uma e aunoa ma oe.","Nisi mea e te le faatalitalia. O se leoleo po e faatumu le koluma E fai a e moe oe, ma filifili kāte e le manaʻomia ai se tali. O se tagaga token e faaali le aofaʻi e faaaoga e sui, ma o le Auala e leai ni token e taofi ai. E mafai ona e feʻau atu i uo, faamaufaailogaina mai le pito i le pito. E tautala le laupapa i le tusa ma le 120 gagana, e aofia ai Holani, pirate ma Klingon. E leai se totogi, ma e leai se tasi o taumafai e faatau atu.","O le AI-gile o se poloketi laʻitiiti totino, e le o se kamupani. Na manaʻo Rich e tausia ni poloketi tusi polokalama AI e aunoa ma le tatalaina o polokalama uma, o lea na ia fausia ai se laupapa faatasi ma sui, ona faaaoga lea e fausia le vaega o totoe. O loo i le pre-alpha tapunia: e galue, e tele lava, mo ni uo e toʻaitiiti. E leai se itulau o tau, e leai se nusipepa. Afai e aogā, talosaga e taumafai pe a sili atu le tatala."]},{"n":144,"texts":["O le AI-gile o se laupapa kanban mo le tagata e tasi ma le tele o sui AI. E galue i lau lava komepiuta ma e leai lava se totogi. E te faaopoopo poloketi, ma taʻitasi e maua se taʻitaʻi ma se ʻau laʻitiiti. E te talanoa ma le taʻitaʻi, e pei o Discord, ma faamatala se manatu; e liliu e le taʻitaʻi i kāte ma se fuafuaga, ona faatali lea seʻia e kiliki Alu. E faia e le ʻau kāte e tusa ai ma le faamuamua, e faaaoga se laina poloaiga faigofie na faia mo faiga gagana. Aʻo leʻi toe foʻi se mea ia te oe, e mulimuli se AI suʻesuʻe i laasaga i se kopi o le polokalama ma faapipiʻi se ata o le mataʻitusi. O galuega ua uma e oo i lau faaputuga faatasi ma faila ua suia ma eseesega. E te talia, pe tuu se faamatalaga ona ala lea o le ʻau ma toe taumafai. Na o oe e mafai ona e suia se kāte i le Ua uma.","O se aso ma AI-gile, tusa lava. I le afiafi e te tuu ni faamatalaga: o lenei faamau o loo i se mea sese, o lena lisi e tatau ona faatulagaina, e mafai ona tatou maua se auala pogisa. E te alu e moe. E faitau e sui faamatalaga, faia suiga, suʻesuʻe ma toe tuuina atu ia te oe. Afai e mutu le koluma E fai, e faatumuina e le leoleo po mai le backlog i kāte e le manaʻomia ai se tali mai ia te oe. I le taeao o loo iai se faaputuga puupuu: ni fesili e ono ma ni mea e suʻesuʻe, taʻitasi ma laasaga e mafai e se tagata moeiini ona mulimuli ai ma se ata o loo galue. E te alu i totonu, talia mea lelei ma toe auina atu isi. Ona e taumafa lea o le taeao, lea e le mafai pea e sui ona fesoasoani i ai.","Muamua, le mea e le o le AI-gile. E le o se startup, e le o faatauina, ma e leai se tasi o aoina au faamatalaga. O se laupapa e leai se totogi e galue i lau komepiuta, e leai ni teugatupe, e leai ni nofoaga mulimuli ma e leai ni cookies. O le mea e iai: o se nofoaga e tasi mama e vaai ai i poloketi tusi polokalama AI uma i le taimi e tasi, ma se ʻau o sui e faia kāte ma oe e faia filifiliga. E tuufaatasia kāte felavasaʻi, faasaʻo ulutala fenumiai, ma mataʻituina ia tumau le code vaivai. E tautala i le tusa ma le 120 gagana, mai le Holani ma le Flemish i le pirate ma le Klingon. O loo i le pre-alpha tapunia, o lea e faigata i nisi pito. Afai e foliga manaia, talosaga ma le agalelei ona e maua lea ma le vave."]}],"quips":{"1":"Le upu e tasi. Natia. Masalo e sili.","3":"Upu e tolu. E sili atu le faamaoni nai lo le tele o itulau o oloa.","8":"Upu e valu. E puupuu pea nai lo se fono puupuu.","21":"O umi o story points, i le ala. Ioe, e faapea lava.","55":"Upu e lima sefulu ma le lima. E lua kāte na uma aʻo e faitau.","144":"O le mea umi lea. E leai se 233. Ua alu e moe sui."}},"timeline":{"first-idea.name":"Le manatu muamua","first-idea.line":"O le talanoaga sili ona muamua, aʻo leʻi iai se code.","first-board.name":"Le laupapa muamua","first-board.line":"O se laupapa e mulimuli i lona lava fausiaga: kāte, koluma, toso ma tuu, poloketi.","team-roles.name":"ʻAu ma tofiga","team-roles.line":"Faamatalaga o sui, faʻataʻitaʻiga o ʻau, avanoa ma o ai e faia le a.","install.name":"Faapipiʻiga ma lomiga","install.line":"O se zip e mafai e se uo ona faapipii, faafouga otometi, auala ma toe foʻi.","usage-saver.name":"Faasaoina o le faaaogaina","usage-saver.line":"Fuaina le tau o le faatinoga, tausia le code e vaivai, faasaoina lau tapulaa.","friends.name":"Uo ma le faasoaina","friends.line":"Feʻau tuusao, se relay faalilolilo, valaaulia, tofiga ma poloketi faasoa.","languages.name":"Gagana","languages.line":"O tusitusiga uma o le mataʻitusi i se faila gagana, ma le Holani ma le Flemish muamua.","ai-tester.name":"AI suʻesuʻe","ai-tester.line":"E muamua siaki e se suʻesuʻe tuuina atu uma ma faaali le mea na ia vaai i ai.","website.name":"Le initaneti","website.line":"aigile.lol, le teaser ma lenei taimi.","streaming.name":"Talanoaga ma faasalalauga","streaming.line":"Discord, Twitch, OBS, auala faasalalau, GIF ma emoji.","no-ai.name":"Lomiga e leai se AI","no-ai.line":"O se laupapa mo tagata e tusi polokalama e aunoa ma AI, ma laupapa lautele.","night-watch.name":"Leoleo po","night-watch.line":"O se leoleo ma se Scrum Master e tausia ʻau i galuega a e moe oe.","p-more.name":"Isi mea uma","p-more.line":"Manatu laiti o loo faatali pea i le latou taimi.","p-android.name":"Telefoni ma Android","p-android.line":"Oo atu i lau laupapa mai se telefoni, ona sosoo ai lea ma se polokalama Android.","p-release.name":"Alpha ma mulimuli ane","p-release.line":"Alpha tapunia, le initaneti ola, ona sosoo ai lea ma le beta.","p-languages.name":"Sili atu gagana","p-languages.line":"E 130 gagana, ma se auala faʻalauteleina o le gagana mo i latou o aʻoaʻo.","p-engines.name":"Sili atu afi AI","p-engines.line":"Filifili Claude, Codex, Gemini, Copilot po o Cursor mo sooupu taʻitasi.","p-pro.name":"Faiga faapolofesa","p-pro.line":"Faailoga o lamatiaga, faitotoʻa tuufaatasia, kāte o mea e tutupu ma puipuiga.","p-self.name":"Tausia oe","p-self.line":"Auala o le vaivai, faamanatu o le tausiga o oe lava ma le 4:20.","p-servers.name":"Server ma le tuputupu aʻe","p-servers.line":"Setiina lautele o server, tofiga ma fuafuaga mo le tuputupu aʻe.","p-livestream.name":"Faaopoopoga faasalalau","p-livestream.line":"Talanoaga Twitch, emoji faapitoa ma se vaaiga ola lautele."},"words":{"button":"📖 Upu faʻapitoa","h":"📖 Upu ua faamatalaina","intro":"O upu e te feiloaʻi ai i le AI-gile, i se gagana faigofie: o le fausiaina, o le suia ma le saogalemu, o le faagaoioia pea mo tagata e faʻaaogaina, ma le galulue faatasi o se ʻau ma le AI.","search":"Su'e se upu…","none":"E leai se upu e fetaui.","close":"Tapuni","count":{"one":"{count} upu","other":"{count} upu"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Fausiaina"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Suia ma le saogalemu"},{"id":"run","name":"🛎️ Faagaoioia o se auaunaga"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Manatu ma galuega e leʻi fuafuaina. E leai se mea iina e galueina seʻia siitia i le E fai."},{"id":"sprint","g":"agile","word":"Sprint","text":"O se vaitaimi puʻupuʻu o galuega (e masani ose vaiaso po o le lua) ma se aofa'iga o kāte ua maliega e faamaeaina.","also":["sprints"]},{"id":"standup","g":"agile","word":"Fonotaga puʻupuʻu","text":"O se siakiga vave: o le a le mea na faia e sui taʻitasi o le 'au, o le a le mea latou te faia a sosoo, ma le mea o taofia ai i latou.","also":["standup","stand-ups","stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"O se laupapa e iai koluma (E fai, O faia, Ua uma) e siitia ai kāte mai le agavale i le taumatau a o faia galuega."},{"id":"wip","g":"agile","word":"Tapulaʻa WIP","text":"Galuega o faagaoioi: le tele aupito o kāte e tatau ona taofi e se koluma, ina ia faamaea e le 'au mea a o leʻi amata nisi.","also":["WIP","WIP limit"]},{"id":"dod","g":"agile","word":"Faauigaga o le Uma","text":"O le lisi siaki puupuu a le ʻau o le uiga o le “uma”, e pei o le ua suʻeina ma faamatalaina, a o leʻi tuuina atu se kāte iā te oe. O lona masaga, o le Faauigaga o le Sauni, e faailoa mai pe a manino lelei se kāte e amata ai.","also":["Definition of Done","Faauigaga o le Sauni","Definition of Ready"]},{"id":"retro","g":"agile","word":"Toe iloilo","text":"O se toe tilotilo i le auala e galue ai le ʻau, e malilie ai i se mea e tasi e faaleleia. I le AI-gile e fautuaina e se toe iloilo se suiga i auala o galuega a le ʻau, ma e te fai mai Alu pe Leʻi taimi.","also":["retro","retrospective"]},{"id":"swarm","g":"agile","word":"Fuifui","text":"Lima uma i le galuega: e tuu e ʻau uma isi galuega e fesoasoani i se poloketi faanatinati e tasi seʻia foia. E faatali isi poloketi i le taimi lea.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"O le tagata e tausia le tafe o galuega: vaaia kāte ua mau, unaʻia ʻau, ma faamanatu atu iā te oe mea o loo faatali. I le AI-gile e faia lenei mea e le Lead Scrum Master i poloketi uma.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"O le pusa faila o le poloketi o le code ma lona tala atoa o commits, e masani ona teuina foi i le GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"O se laina e ese o galuega i le code, ina ia mafai ona faia suiga e aunoa ma le paʻi i le lomiga autu.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"O se ata ua teuina o le code, faatasi ai ma se faʻamatalaga puʻupuʻu o le mea na suia. E mafai ona e toe foʻi i se tasi i so'o se taimi.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"O le auina atu o ata ua teuina (commits) mai lenei komipiuta i le GitHub, ina ia teuina ma faasoa."},{"id":"merge","g":"build","word":"Merge","text":"O le toe tuufaatasia o suiga a se branch i le lomiga autu."},{"id":"pr","g":"build","word":"Pull request","text":"O le ole atu e siaki ma tuufaatasia suiga a se branch i le lomiga autu.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"O le faʻamama o le code e aunoa ma le suia o mea e faia: faila laiti, igoa manino, e itiiti le toe faia."},{"id":"bug","g":"build","word":"Bug","text":"O se mea e le galue e pei ona tatau.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Iloiloga a paaga","text":"O se isi pea mata: e siaki e se isi AI le galuega a kāte taʻitasi a o leʻi oʻo mai iā te oe, ina ia itiiti ni mea sese e pasi atu.","also":["peer review","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"O le taumafai i se galuega ua uma e siaki pe faia le mea na ole atu ai, a o leʻi taliaina.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"O le faapuupuuga o le quality assurance: o siaki otometi e faia a o leʻi ola se mea. A mumu le QA, ua toilalo se mea, ma e le mafai ona ola seʻia toe faasaʻo.","also":["siaki o le tulaga lelei","quality assurance"]},{"id":"testpile","g":"test","word":"Faaputuga suʻega","text":"O kāte ua uma o loo faatali mo oe e taumafai ai, tasi i le tasi. Talia se tasi pe toe faafoi atu ma se faamatalaga, ona sau ai lea o le isi.","also":["test pile"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"O le tuuina atu o se lomiga fou ia ola, e pei o se sava e faʻaoga ai e tagata."},{"id":"release","g":"change","word":"Lomiga","text":"O se fusi ua faaigoaina o galuega ua uma e ola faatasi, faatasi ai ma ni faamatalaga puupuu o mea na suia. E tusia e 🚀 Lomiga ia faamatalaga mai kāte ua uma.","also":["lomiga fou","release","releases"]},{"id":"rollback","g":"change","word":"Toe faafoi","text":"O le toe foʻi i le lomiga mulimuli na aoga pe a faʻatupu faʻafitauli se lomiga fou. I le AI-gile e faia ai se lisi siaki o laasaga e toe faaleaogaina ai, na tusia i suiga taʻitasi.","also":["rollback","roll back","ua toe faafoi"]},{"id":"live","g":"change","word":"Ola","text":"O le lomiga moni e faʻaaogaina e tagata, e ese mai i se kopi e taumafai ai mea. E taʻua foʻi e le au atiaʻe o le production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Suiga","text":"O se suiga ua fuafuaina i se mea e faalagolago i ai tagata, e tusia muamua: o le a, aisea, le lamatiaga, afea, ma le auala e toe faaleaogaina ai. Amata i le 🔀 Talosaga se suiga.","also":["suiga","talosaga mo se suiga","change"],"noTip":1},{"id":"risk","g":"change","word":"Lamatiaga","text":"O se mea e ono sese, ua fuaina i le avanoa e tupu ai ma le leaga pe a tupu. E teuina e ⚠️ Lamatiaga i se lisi e tasi, o le togi maualuga muamua, e taʻitasi ma se aso e toe vaai ai.","also":["lamatiaga","risk","risks"]},{"id":"chgwin","g":"change","word":"Faamalama o suiga","text":"O taimi e mafai ai ona ola suiga, e pei o se afiafi filemu o le Aso Lua. I fafo atu o se faamalama, e le mafai ona faauma se kāte suiga, vagana ua faafuaseʻi.","also":["faamalama o suiga","change window"]},{"id":"gonogo","g":"change","word":"Alu / aua le alu","text":"O se palota vave a o leʻi ola se suiga: o tagata taʻitasi e tatau ona faatagaina e fai mai Alu pe Aua le alu. E faaauau pe a malilie uma.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Faatagaga","text":"O le faatali mo se ioe a o leʻi amata le galuega. O se kāte e talosagaina e se uo, po o se suiga, e faatali i ✅ Faatagaga seʻia e talia pe teena.","also":["faatagaga","approval"]},{"id":"quiettime","g":"change","word":"Taimi filemu","text":"O se vaitaimi, e pei o se stream, se faataʻitaʻiga po o le po, e leai se mea e ola ai. E faaauau pea ona galulue ma suʻe le ʻau, ae e faatali le ola seʻia uma. I isi nofoaga e taʻua o le change freeze.","also":["taimi filemu","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Auaunaga","text":"O se mea na e fausia e faalagolago i ai tagata, e pei o se upegatafaʻilagi po o se app, e tausia ina ia aoga pea. Faailoga le “O lenei poloketi o se auaunaga” ma taʻu le mea e ofo atu, o ai e faʻaaogaina, ma o ai o loo i le tiute.","also":["auaunaga","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Siaki o le ola","text":"O se siaki otometi, i minute nai taʻitasi, pe o tali mai pea lau auaunaga. Afai e toilalo faafaasolo ni nai taimi, e tatala e le AI-gile lava ia se kāte o se mea ua tupu.","also":["uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Itulau o le tulaga","text":"O se itulau lautele e faaali ai pe o aoga se auaunaga (lanu meamata, moli po o le mumu) ma le tala fou lata mai, ina ia mafai e tagata e faʻaaogaina ona siaki nai lo le fesili.","also":["status page"]},{"id":"desk","g":"run","word":"Laulau auaunaga","text":"O le nofoaga e oo mai ai fesili ma lipoti mai tagata o loʻo faʻaaogaina lau auaunaga. E faavasega e AI-gile taʻitasi o se talosaga, o se mea ua tupu po o se manatu, ma faʻailoa atu pe a foliga e pei o se mea ua uma ona lipotia.","also":["laulau","help desk","helpdesk","service desk"]},{"id":"svcrequest","g":"run","word":"Talosaga mo auaunaga","text":"Pe a talosaga se tasi mo se mea masani, e pei o se faʻamaumauga fou po o sina fesoasoani, nai lo le lipotia o se mea ua malepe. E faatali i lona taimi; e muamua le mea ua tupu.","also":["talosaga","service request"]},{"id":"incident","g":"run","word":"Mea ua tupu","text":"O se mea ua malepe i le taimi nei mo tagata o loo faʻaaogaina, e pei o le upegatafaʻilagi ua pau. E muamua le kāte 🔥 mea ua tupu i le laina: o le toe faaaogaina o le mea muamua.","also":["faalavelave","incident"]},{"id":"major","g":"run","word":"Mea ua tupu tele","text":"O se mea ua tupu tele: e toʻatele tagata ua aʻafia, po o tupe po o faamaumauga ua lamatia. E tasi le faamau e tuʻu ai ʻau uma i ai (fuifui), fafagu le tagata o loo i le tiute, ma talosaga mo se tala fou o le tulaga i minute e 30 taʻitasi.","also":["faalavelave tele","major incident"]},{"id":"oncall","g":"run","word":"I le tiute","text":"O le avea ma tagata e tali pe a malepe se mea, e oo lava i le po. O auaunaga taʻitasi e iai se sui o le ʻau o loo i le tiute e fafagu muamua mo ona mea ua tutupu.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Taimi o tali","text":"Le umi e mafai ai e se kāte ona faatali mo se tali muamua, mo se faataʻitaʻiga e tasi le itula mo se mea ua tupu. A uma lea e maua ai se uati mumu, ina ia leai se mea e galo filemu. E taʻua foʻi o le taimi faatulagaina o tali.","also":["taimi o tali","response target"]},{"id":"postmortem","g":"run","word":"Iloiloga pe a uma","text":"O se toe tilotilo puupuu pe a uma se mea ua tupu: o le mea na tupu, o le mea na fesoasoani, ma le mea e suia, e aunoa ma le tuuaʻia o se tasi. E le mafai ona tapunia se mea ua tupu e aunoa ma se tasi.","also":["post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Faʻafitauli","text":"O le mafuaaga lilo i tua o se tasi pe sili atu mea ua tutupu. E faapotopoto e se kāte 🧩 faʻafitauli mea ua tutupu e toe foʻi mai pea, ina ia maua le mafuaaga ma faasaʻo e faavavau.","also":["faafitauli","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Mafuaaga autu","text":"O le mafuaaga moni na malepe ai se mea, ae le na o le mea na e vaaia ua sese. Faasaʻo le mafuaaga autu ona le toe foʻi mai lea o le mea ua tupu.","also":["root cause"]},{"id":"workaround","g":"run","word":"Fofo mo le taimi nei","text":"O se auala e aoga pea ai mea seʻia sauni le faasaʻoga moni, e pei o le toe amataina o se mea pe a mau. E tusia i le kāte faʻafitauli ina ia le toe sailia e se tasi.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Mea sese ua iloa","text":"O se faʻafitauli ua malamalama i lona mafuaaga ma e iai se fofo mo le taimi nei, ae leʻi faasaʻoina. E lisi e 🧩 Mea sese ua iloa, ina ia faʻaaoga e tagata uma le fofo mo le taimi nei nai lo le toe eli.","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"O faatonuga laasaga ma laasaga e faasaʻo ai se ituaiga faʻafitauli ua iloa, ina ia faia i le auala lava e tasi, vave, i taimi uma. A uma se mea ua tupu tele, e mafai e le ʻau ona fautuaina se tasi mo lau ioe.","also":["runbooks"]},{"id":"ci","g":"run","word":"Mea faatulagaina","text":"O se mea e tasi e faalagolago i ai lau auaunaga, e pei o se server, se domain, se tusi faamaonia, se ki po o se kamupani e tuʻuina mai mea. O le 🗂️ Mea faatulagaina e lisi ai i latou mo auaunaga taʻitasi, ina ia e iloa le mea e aafia i se mea ua tupu ma le mea e manaʻomia ona faʻafouina pe faʻasao se kopi.","also":["mea faatulagaina","configuration item"]},{"id":"expiry","g":"run","word":"Aso e uma ai","text":"E mataʻituina e AI-gile aso e pei o le taimi e uma ai se tusi faamaonia po o se domain. I aso e 30 a o lei oo i lena aso, e faia ai e ia se kāte e tasi e faʻafou ai, ina ia le taofi faafuasei ona galue se mea.","also":["aso e uma ai","uma le taimi","expiry"]},{"id":"backup","g":"run","word":"Kopi faasao","text":"O se kopi ua teuina o au faamaumauga mai muamua, e toe faalagolago i ai pe a leiloa pe faaleagaina se mea. E faia e le AI-gile se kopi faasao o au laupapa i aso uma.","also":["backup","backups"]},{"id":"restore","g":"run","word":"Toe aumai","text":"O le toe tuʻuina mai o faamaumauga mai se kopi faasao. E moni lava le aoga o se kopi faasao pe a e iloa e mafai ona toe aumai, o lea e lelei ona taumafai i lea taimi ma lea taimi.","also":["restore","toe faafoi mai"]},{"id":"svcreview","g":"run","word":"Iloiloga o le auaunaga","text":"O se toe tilotilo i le masina e tasi o se auaunaga: mea ua tupu na tatala ma faasaʻo, le vave o le maua e tagata o se tali, le taimi na ola ai ma tokena na faʻaaogaina. E faʻaali e le Iloiloga o le masina lenei mea mo auaunaga taʻitasi.","also":["iloiloga o le masina","service review"]},{"id":"accessreview","g":"run","word":"Iloiloga o le ulufale","text":"O le siakiina i aso uma e 90 po o ai e mafai pea ona ulufale: soʻoga faasoa, matafaioi a uo ma mea faalilolilo ua teu. E te teu pe aveese taʻitasi, ina ia le tumau le ulufale tuai.","also":["access review"]},{"id":"improvements","g":"run","word":"Lisi o faaleleiga","text":"O mea uma na filifili le ʻau e faalelei atili, i se nofoaga e tasi: fautuaga mai le toe iloilo, galuega mai iloiloga ma faasaʻoga o faʻafitauli, taʻitasi ma lona tulaga. Saili i le 📈 Faaleleiga.","also":["faaleleiga","improvements"]},{"id":"tokencap","g":"run","word":"Tapulaa tokena","text":"O se tapulaa i le masina mo tokena e mafai ona faʻaaoga e sooupu o se auaunaga. I le 80% e te maua ai se lapataiga; i le 100% e faatali a latou galuega i tua seia oo i le masina fou pe seia e siitia le tapulaa.","also":["tapulaa token","token cap"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Sooupu","text":"O se AI e galue na o ia i se galuega: faitau le code, faia suiga, faagaoioi siakiga, ma lipotia mai.","also":["agent","agents","sooupu"]},{"id":"token","g":"ai","word":"Token","text":"O le iunite e faitauina ai le faʻaaogaina o le AI: pe tusa ma ni nai mataitusi o tusitusiga ua faitau po o tusia. E itiiti token, e tele totoe o lau fuafuaga.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"O se poloaiga laiti e faagaoioi e ia lava i se taimi ua seti, e.g. pe a amata se sesisi AI, ina ia faʻalogo le 'au i au faʻamatalaga.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
